"""Bahasa Melayu — akidah dan ibadah (faith_001 … faith_070)."""

T = {
"faith_001": ("Berapakah jumlah Rukun Islam?", ["5", "4", "6", "7"], "Hadis Jibril dan hadis yang diriwayatkan Ibnu Umar menyenaraikan lima Rukun Islam."),
"faith_002": ("Apakah nama pengakuan iman dalam Islam?", ["Syahadah", "Solat", "Zakat", "Haji"], "Syahadah, kesaksian iman, ialah Rukun Islam yang pertama."),
"faith_003": ("Berapa kali sehari solat fardu dilaksanakan dalam Islam?", ["5", "3", "4", "7"], "Lima solat fardu harian ialah rukun asas Islam."),
"faith_004": ("Apakah nama sedekah wajib dalam Islam?", ["Zakat", "Sedekah", "Wakaf", "Kaffarah"], "Zakat ialah sedekah wajib, salah satu daripada lima Rukun Islam."),
"faith_005": ("Apakah nama bulan puasa wajib dalam Islam?", ["Ramadan", "Syawal", "Rejab", "Muharam"], "Al-Quran memerintahkan berpuasa pada bulan Ramadan."),
"faith_006": ("Apakah nama ibadah ke Makkah yang wajib sekali seumur hidup bagi yang berkemampuan?", ["Haji", "Umrah", "Iktikaf", "Tawaf"], "Al-Quran mewajibkan haji, sekurang-kurangnya sekali seumur hidup, bagi sesiapa yang mampu melaksanakannya."),
"faith_007": ("Ke arah manakah orang Islam menghadap ketika solat?", ["Kaabah, di Makkah", "Baitulmaqdis", "Madinah", "Timur"], "Al-Quran menetapkan Kaabah sebagai arah solat (kiblat)."),
"faith_008": ("Menurut hadis yang terkenal, berapakah Rukun Iman yang lazim diajarkan?", ["6", "4", "5", "7"], "Hadis Jibril menyenaraikan enam Rukun Iman: Allah, para malaikat, kitab-kitab, para rasul, hari Akhirat, dan qada' dan qadar."),
"faith_009": ("Apakah nama bersuci dengan air yang dilakukan seorang Muslim sebelum setiap solat?", ["Wuduk", "Tayamum", "Mandi wajib", "Siwak"], "«Apabila kamu hendak mengerjakan solat, maka basuhlah muka kamu dan tangan kamu…»: inilah wuduk."),
"faith_010": ("Menurut al-Quran, apakah yang dilakukan «para pencatat yang mulia» (kiraman katibin)?", ["Mencatat amalan manusia", "Memikul Arasy", "Menjaga syurga", "Menurunkan hujan"], "«Padahal sesungguhnya ada malaikat-malaikat yang mengawasi kamu, yang mulia dan mencatat»: para malaikat mencatat setiap amalan."),
"faith_011": ("Berapakah jumlah nama-nama Allah yang indah yang disebut dalam riwayat sahih?", ["99", "50", "100", "114"], "Hadis sahih yang diriwayatkan al-Bukhari dan Muslim menyebut sembilan puluh sembilan nama: seratus kurang satu."),
"faith_012": ("Apakah maksud nama Allah «Ar-Rahman»?", ["Yang Maha Pemurah", "Yang Maha Pencipta", "Yang Maha Berkuasa", "Yang Maha Mengetahui"], "Ar-Rahman, Yang Maha Pemurah: rahmat-Nya meliputi segala sesuatu."),
"faith_013": ("Dalam Al-Fatihah, Allah disebut «Pemilik» hari apa?", ["Hari Pembalasan", "Hari Jumaat", "Hari pertama", "Hari Arafah"], "«Pemilik hari Pembalasan»: hari setiap orang menemui amalannya."),
"faith_014": ("Pada hari apakah dalam seminggu al-Quran menyeru orang beriman kepada solat berjemaah?", ["Jumaat", "Isnin", "Sabtu", "Ahad"], "«Apabila diseru untuk mengerjakan solat pada hari Jumaat, maka segeralah kamu mengingati Allah.»"),
"faith_015": ("Menurut al-Quran, siapakah yang menjamin al-Quran terpelihara daripada sebarang perubahan?", ["Allah sendiri", "Hanya para malaikat", "Para ulama", "Raja-raja"], "«Sesungguhnya Kamilah yang menurunkan al-Quran, dan sesungguhnya Kami yang memeliharanya.»"),
"faith_016": ("Apakah yang al-Quran nyatakan tentang memasuki agama?", ["Tiada paksaan dalam beragama", "Ia dilakukan dengan sumpah", "Ia memerlukan saksi", "Ia berlaku ketika dewasa"], "«Tiada paksaan dalam agama; sesungguhnya telah jelas jalan yang benar daripada jalan yang sesat.»"),
"faith_017": ("Apakah salam orang Islam, satu doa keselamatan?", ["Assalamualaikum", "Marhaban", "Sabahul khair", "Ahlan wa sahlan"], "«Assalamualaikum»: semoga keselamatan ke atas kamu, dijawab dengan «waalaikumussalam»."),
"faith_018": ("Apakah nama kepercayaan kepada keesaan Allah, inti pati Islam?", ["Tauhid", "Tafsir", "Tajwid", "Tarawih"], "Tauhid, menegaskan bahawa Allah Maha Esa tanpa sekutu, ialah asas seluruh keimanan."),
"faith_019": ("Kitab apakah yang Allah turunkan kepada Nabi Musa?", ["Taurat", "Injil", "Zabur", "Al-Quran"], "«Sesungguhnya Kami telah menurunkan Kitab Taurat, di dalamnya ada petunjuk dan cahaya» (5:44)."),
"faith_020": ("Kitab apakah yang Allah berikan kepada Nabi Isa?", ["Injil", "Taurat", "Zabur", "Suhuf Ibrahim"], "«Kami berikan kepadanya Kitab Injil yang di dalamnya ada petunjuk dan cahaya» (5:46)."),
"faith_021": ("Menurut al-Quran, apakah yang perlu dilakukan apabila diberi salam?", ["Membalas dengan salam yang lebih baik, atau yang serupa", "Berdiam diri", "Menunduk", "Hanya membalas rakan"], "«Apabila kamu diberi penghormatan dengan sesuatu ucapan, maka balaslah dengan yang lebih baik daripadanya, atau balaslah dengan yang serupa» (4:86)."),
"faith_022": ("Surah Al-A'la menyebut «Suhuf» (lembaran-lembaran) dua orang nabi. Siapakah mereka?", ["Ibrahim dan Musa", "Nuh dan Hud", "Daud dan Sulaiman", "Zakaria dan Yahya"], "«Sesungguhnya ini terdapat dalam kitab-kitab yang dahulu, iaitu kitab-kitab Ibrahim dan Musa» (87:18-19)."),
"faith_023": ("Apakah nama malaikat penjaga neraka yang disebut dalam al-Quran?", ["Malik", "Ridwan", "Mikail", "Israfil"], "Penghuni neraka akan menyeru: «Wahai Malik, biarlah Tuhanmu mematikan kami sahaja!» (43:77)."),
"faith_024": ("Menurut surah Al-Haqqah, berapakah malaikat yang memikul Arasy Allah pada hari Kiamat?", ["Lapan", "Empat", "Dua belas", "Satu"], "«Dan pada hari itu lapan malaikat menjunjung Arasy Tuhanmu di atas mereka» (69:17)."),
"faith_025": ("Menurut al-Quran, siapakah yang ditugaskan mencabut nyawa ketika kematian?", ["Malaikat maut", "Jibril", "Nabi", "Jin"], "«Katakanlah: Malaikat maut yang ditugaskan untuk kamu akan mematikan kamu» (32:11)."),
"faith_026": ("Daripada apakah para malaikat diciptakan, menurut hadis dalam Sahih Muslim?", ["Daripada cahaya", "Daripada api", "Daripada tanah liat", "Daripada air"], "«Para malaikat diciptakan daripada cahaya, jin daripada nyalaan api, dan Adam daripada apa yang telah dijelaskan kepada kamu.»"),
"faith_027": ("Daripada apakah jin diciptakan, menurut al-Quran?", ["Daripada nyalaan api tanpa asap", "Daripada cahaya", "Daripada tanah liat", "Daripada angin"], "«Dan Dia menciptakan jin daripada nyalaan api tanpa asap» (55:15)."),
"faith_028": ("Siapakah yang al-Quran namakan sebagai musuh yang nyata bagi manusia?", ["Syaitan", "Para malaikat", "Haiwan", "Malam"], "«Sesungguhnya syaitan itu musuh bagi kamu, maka jadikanlah ia musuh» (35:6)."),
"faith_029": ("Berapakah jumlah nabi yang digelar «Ulul Azmi» (yang mempunyai keteguhan hati)?", ["Lima: Nuh, Ibrahim, Musa, Isa dan Muhammad ﷺ", "Tiga", "Sepuluh", "Dua puluh lima"], "«Bersabarlah engkau sebagaimana bersabarnya rasul-rasul Ulul Azmi» (46:35); surah Asy-Syura (42:13) menyebut kelima-lima nabi ini bersama."),
"faith_030": ("Apakah yang akan ditiup untuk mengumumkan hari Kebangkitan, menurut al-Quran?", ["Sangkakala", "Tanduk biri-biri", "Seruling", "Loceng"], "«Sangkakala pun ditiup, lalu matilah semua yang di langit dan di bumi… kemudian ditiup sekali lagi» (39:68)."),
"faith_031": ("Apakah nama yang al-Quran berikan kepada alat penimbang amalan pada hari Kiamat?", ["Neraca (al-mawazin)", "Catatan", "Titian", "Sangkakala"], "«Kami akan memasang neraca yang adil pada hari Kiamat, maka tiada seorang pun yang dirugikan walau sedikit» (21:47)."),
"faith_032": ("Apakah nama yang al-Quran berikan kepada tingkatan syurga tertinggi yang dijanjikan kepada orang yang beriman dan beramal soleh?", ["Firdaus", "Al-Kauthar", "As-Sirat", "Al-A'raf"], "«Sesungguhnya orang yang beriman dan beramal soleh, bagi mereka syurga Firdaus sebagai tempat tinggal» (18:107)."),
"faith_033": ("Apakah nama neraka yang paling kerap disebut dalam al-Quran?", ["Jahanam", "Firdaus", "Kauthar", "Tasnim"], "Al-Quran menyebut neraka «Jahanam» berpuluh-puluh kali, contohnya: «Kamu akan dihimpunkan ke neraka Jahanam» (3:12)."),
"faith_034": ("Rukun Iman manakah yang ditegaskan oleh ayat «Sesungguhnya Kami menciptakan segala sesuatu menurut takdir»?", ["Iman kepada qada' dan qadar", "Iman kepada malaikat", "Iman kepada kitab-kitab", "Iman kepada para rasul"], "«Sesungguhnya Kami menciptakan segala sesuatu menurut takdir (qadar)» (54:49): tiada apa yang berlaku di luar ilmu dan kehendak Allah."),
"faith_035": ("Dosa apakah yang Allah nyatakan tidak akan diampuni bagi orang yang mati tanpa bertaubat daripadanya?", ["Syirik (mempersekutukan Allah)", "Berdusta", "Bakhil", "Marah"], "«Sesungguhnya Allah tidak mengampuni dosa syirik, dan Dia mengampuni dosa selain itu bagi sesiapa yang Dia kehendaki» (4:48)."),
"faith_036": ("Menurut al-Quran, siapakah yang Allah cintai dalam kalangan orang yang berdosa?", ["Orang yang bertaubat", "Orang yang menyembunyikan dosanya", "Orang yang berputus asa", "Orang yang menyalahkan orang lain"], "«Sesungguhnya Allah mencintai orang yang bertaubat dan mencintai orang yang menyucikan diri» (2:222)."),
"faith_037": ("Menurut surah Nuh, apakah yang dibawa istighfar (memohon ampun) kepada sesuatu kaum?", ["Hujan yang lebat dan keberkatan", "Tiada apa-apa", "Kemarau", "Tidur yang panjang"], "«Mohonlah ampun kepada Tuhan kamu, sesungguhnya Dia Maha Pengampun, nescaya Dia akan menurunkan hujan yang lebat kepada kamu» (71:10-11)."),
"faith_038": ("Apakah yang al-Quran janjikan kepada orang yang bertawakal kepada Allah?", ["Allah mencukupkan keperluannya", "Dia akan menjadi kaya", "Dia tidak akan sakit", "Dia tidak perlu bekerja lagi"], "«Dan sesiapa yang bertawakal kepada Allah, nescaya Allah mencukupkan keperluannya» (65:3)."),
"faith_039": ("Apakah firman Allah tentang doa dalam surah Ghafir?", ["«Berdoalah kepada-Ku, nescaya Aku perkenankan bagi kamu»", "«Berdoalah hanya pada waktu malam»", "«Berdoalah kepada para malaikat»", "«Doa hanya untuk para nabi»"], "«Tuhan kamu berfirman: Berdoalah kepada-Ku, nescaya Aku perkenankan bagi kamu» (40:60)."),
"faith_040": ("Dengan apakah, menurut al-Quran, hati menjadi tenteram?", ["Dengan mengingati Allah (zikir)", "Dengan wang", "Dengan tidur", "Dengan bermusafir"], "«Ketahuilah, hanya dengan mengingati Allah hati menjadi tenteram» (13:28)."),
"faith_041": ("Apakah solat fardu pertama dalam sehari?", ["Subuh (Fajar)", "Zuhur", "Asar", "Isyak"], "Lima solat mengikut urutan: Subuh, Zuhur, Asar, Maghrib dan Isyak."),
"faith_042": ("Berapa rakaat solat fardu Subuh?", ["Dua", "Tiga", "Empat", "Satu"], "Subuh dua rakaat; Maghrib tiga; Zuhur, Asar dan Isyak masing-masing empat."),
"faith_043": ("Solat fardu manakah yang mempunyai tiga rakaat?", ["Maghrib", "Subuh", "Zuhur", "Isyak"], "Maghrib, sejurus selepas matahari terbenam, ialah satu-satunya solat fardu yang tiga rakaat."),
"faith_044": ("Apakah nama seruan solat yang dilaungkan dari masjid?", ["Azan", "Khutbah", "Tasbih", "Talbiah"], "Azan dilaungkan oleh muazin sebelum setiap satu daripada lima solat."),
"faith_045": ("Menurut ayat wuduk, sehingga manakah tangan perlu dibasuh?", ["Sehingga siku", "Sehingga pergelangan tangan", "Sehingga bahu", "Hanya tapak tangan"], "«Basuhlah muka kamu dan tangan kamu hingga ke siku, dan sapulah kepala kamu dan basuhlah kaki kamu hingga ke buku lali» (5:6)."),
"faith_046": ("Apakah yang al-Quran benarkan apabila tiada air untuk bersuci sebelum solat?", ["Tayamum dengan debu yang bersih", "Solat tanpa bersuci", "Menangguhkan solat ke hari esok", "Membasuh dengan pasir basah"], "«Lalu kamu tidak mendapat air, maka bertayamumlah dengan debu yang bersih; sapulah muka kamu dan tangan kamu dengannya» (5:6)."),
"faith_047": ("Apakah nama ceramah yang disampaikan imam sebelum solat Jumaat?", ["Khutbah", "Azan", "Iqamah", "Takbir"], "Khutbah Jumaat disampaikan dalam dua bahagian dari atas mimbar, sebelum solat."),
"faith_048": ("Berapakah bahagian daripada simpanan yang telah genap setahun yang dikeluarkan seorang Muslim sebagai zakat?", ["2.5%", "10%", "25%", "1%"], "Zakat wang simpanan ialah seperempat daripada sepersepuluh, iaitu 2.5%, setelah mencapai nisab selama setahun hijrah."),
"faith_049": ("Sedekah khusus apakah yang wajib pada akhir Ramadan, sebelum solat hari raya?", ["Zakat fitrah", "Zakat emas", "Khumus", "Kaffarah"], "Nabi ﷺ mewajibkan zakat fitrah, satu gantang kurma atau barli, bagi setiap Muslim, tua mahupun muda."),
"faith_050": ("Menurut al-Quran, dari bila hingga bila puasa harian Ramadan berlangsung?", ["Dari fajar hingga malam", "Dari tengah hari hingga petang", "Dari matahari terbit hingga tengah hari", "Sepanjang siang dan malam"], "«Makan dan minumlah sehingga jelas bagi kamu benang putih daripada benang hitam, iaitu fajar, kemudian sempurnakanlah puasa hingga malam» (2:187)."),
"faith_051": ("Apakah nama makan sebelum fajar bagi orang yang akan berpuasa?", ["Sahur", "Berbuka (iftar)", "Walimah", "Akikah"], "Nabi ﷺ bersabda: «Bersahurlah kamu, kerana dalam sahur ada keberkatan.»"),
"faith_052": ("Apakah nama makan yang membatalkan puasa ketika matahari terbenam?", ["Berbuka (iftar)", "Sahur", "Tarawih", "Tahajud"], "Berbuka puasa dilakukan sebaik sahaja matahari terbenam, pada waktu solat Maghrib."),
"faith_053": ("Berapakah hari raya (Aidil) dalam Islam setiap tahun?", ["Dua: Aidilfitri dan Aidiladha", "Hanya satu", "Empat", "Dua belas"], "Aidilfitri menutup bulan Ramadan; Aidiladha jatuh pada 10 Zulhijah, semasa musim haji."),
"faith_054": ("Peristiwa apakah yang diperingati oleh Aidiladha?", ["Pengorbanan Ibrahim yang ditebus dengan seekor kibas", "Kelahiran Nabi ﷺ", "Perang Badar", "Penurunan al-Quran"], "Ketika bersedia menyembelih anaknya, Ibrahim melihatnya ditebus: «Kami tebus anak itu dengan seekor binatang sembelihan yang besar» (37:107)."),
"faith_055": ("Pada bulan apakah dalam kalendar Islam ibadah haji dilaksanakan?", ["Zulhijah", "Ramadan", "Muharam", "Rejab"], "Haji dilaksanakan dari 8 hingga 13 Zulhijah, bulan kedua belas dan terakhir dalam tahun hijrah."),
"faith_056": ("Pada hari ke berapa Zulhijah para jemaah haji berwukuf di padang Arafah?", ["Hari ke-9", "Hari ke-1", "Hari ke-10", "Hari ke-27"], "Wukuf di Arafah pada 9 Zulhijah ialah rukun utama haji; Aidiladha jatuh pada keesokan harinya."),
"faith_057": ("Berapa pusingan mengelilingi Kaabah dalam satu tawaf?", ["Tujuh", "Tiga", "Lima", "Sepuluh"], "Tawaf ialah tujuh pusingan mengelilingi Kaabah, melawan arah jam, bermula dari Hajar Aswad."),
"faith_058": ("Berapa kali perjalanan antara Safa dan Marwah dalam sa'i?", ["Tujuh", "Dua", "Empat", "Dua belas"], "Sa'i mengenang pencarian air oleh Hajar untuk Ismail: tujuh kali, dari Safa ke Marwah dan sebaliknya, setiap arah dikira."),
"faith_059": ("Apakah nama keadaan suci yang dimasuki jemaah haji, dengan dua helai kain putihnya?", ["Ihram", "Tawaf", "Wukuf", "Talbiah"], "Dalam ihram, lelaki memakai dua helai kain tanpa jahitan dan jemaah menjauhi wangian, memburu dan bertengkar."),
"faith_060": ("Dengan perkataan apakah talbiah, yang diulang para jemaah dalam perjalanan ke Makkah, bermula?", ["«Labbaikallahumma labbaik» (Aku menyahut panggilan-Mu, ya Allah)", "«Allahu akbar»", "«Subhanallah»", "«Alhamdulillah»"], "Talbiah Nabi ﷺ ialah: «Labbaikallahumma labbaik, labbaika la syarika laka labbaik…»"),
"faith_061": ("Apakah yang dilakukan jemaah haji di Mina apabila melontar batu kecil ke tiga tugu?", ["Melontar jamrah", "Tawaf", "Sa'i", "Wukuf di Arafah"], "Melontar jamrah mengenang Ibrahim yang menghalau syaitan dengan batu; ia dilakukan di Mina pada hari-hari raya."),
"faith_062": ("Di manakah letaknya Hajar Aswad (Batu Hitam)?", ["Di salah satu penjuru Kaabah", "Di Jabal Arafah", "Di Madinah", "Di puncak Jabal Hira"], "Terpasang di penjuru timur Kaabah, ia menandakan titik permulaan setiap pusingan tawaf."),
"faith_063": ("Apakah nama kain hitam besar yang menutupi Kaabah?", ["Kiswah", "Hijab", "Mimbar", "Mihrab"], "Kiswah, yang disulam dengan ayat-ayat berbenang emas, diganti setiap tahun semasa musim haji."),
"faith_064": ("Apakah nama ziarah «kecil» ke Makkah yang boleh dilakukan pada bila-bila masa sepanjang tahun?", ["Umrah", "Haji", "Hijrah", "Ziarah"], "Umrah terdiri daripada ihram, tawaf dan sa'i; berbeza dengan haji, ia tidak terikat pada bulan tertentu."),
"faith_065": ("Apakah maksud nama Allah «Al-Khaliq»?", ["Yang Maha Pencipta", "Yang Maha Pengampun", "Yang Maha Pemberi Rezeki", "Yang Maha Berkuasa"], "«Dialah Allah Yang Menciptakan (Al-Khaliq), Yang Mengadakan, Yang Membentuk Rupa» (59:24)."),
"faith_066": ("Apakah maksud nama Allah «Al-Ghafur»?", ["Yang Maha Pengampun", "Yang Maha Pencipta", "Yang Maha Perkasa", "Yang Maha Pemurah"], "«Janganlah kamu berputus asa daripada rahmat Allah… Dialah Yang Maha Pengampun (Al-Ghafur), Maha Penyayang» (39:53)."),
"faith_067": ("Apakah maksud dua nama Allah «As-Sami'» dan «Al-Basir»?", ["Yang Maha Mendengar dan Yang Maha Melihat", "Yang Maha Berkuasa dan Yang Maha Menghakimi", "Yang Maha Pencipta dan Yang Maha Pemberi Rezeki", "Yang Awal dan Yang Akhir"], "Ayat Isra' ditutup dengan: «Dialah Yang Maha Mendengar (As-Sami'), Maha Melihat (Al-Basir)» (17:1)."),
"faith_068": ("Apakah maksud «As-Samad», nama Allah dalam surah Al-Ikhlas?", ["Tempat bergantung segala sesuatu, yang tidak bergantung kepada apa pun", "Yang mengampuni", "Yang mendengar", "Yang mencipta"], "«Allahus-Samad» (112:2): Penguasa mutlak yang kepada-Nya semua makhluk bergantung untuk keperluan mereka."),
"faith_069": ("Dua nama Allah manakah yang membuka Ayat Kursi, sejurus selepas «Allah, tiada tuhan selain Dia»?", ["Al-Hayy dan Al-Qayyum (Yang Maha Hidup, Yang Berdiri Sendiri)", "Ar-Rahman dan Ar-Rahim", "Al-Malik dan Al-Quddus", "Al-'Aziz dan Al-Hakim"], "«Allah, tiada tuhan selain Dia, Yang Maha Hidup, Yang Sentiasa Mengurus makhluk-Nya» (2:255)."),
"faith_070": ("Apakah maksud nama Allah «Ar-Razzaq»?", ["Yang Maha Pemberi Rezeki", "Yang Maha Pengampun", "Yang Maha Adil", "Yang Maha Lembut"], "«Sesungguhnya Allah, Dialah Pemberi rezeki (Ar-Razzaq), yang mempunyai kekuatan lagi Maha Kukuh» (51:58)."),
}
